def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 0:
        return ""

    # Stack stores tuples of (sum, length, average)
    stack = []

    for x in a:
        if not stack or stack[-1][0] / stack[-1][1] >= x:
            # Current element forms its own group or new group starts
            stack.append((x, 1, float(x)))
        else:
            # Current element should be merged with previous groups
            curr_sum = x
            curr_len = 1

            while stack and stack[-1][0] / stack[-1][1] > curr_sum / curr_len:
                top_sum, top_len, _ = stack.pop()
                curr_sum += top_sum
                curr_len += top_len

            stack.append((curr_sum, curr_len, curr_sum / curr_len))

    result = []
    for s, l, avg in stack:
        for _ in range(l):
            result.append(avg)

    return '\n'.join(f"{r:.20g}\n" if r != int(r).rstrip('0') + '.0' else f"{int(r)}" 
                     for r in result).rstrip('\n')
