        for i in range(n):
            parts = list(map(int, lines[idx + i].split()))
            if parts[0] == -1:
                is_leaf.append(False)
                value.append(-1)
                left.append(parts[1])
                right.append(parts[2])
            else:
                is_leaf.append(True)
                value.append(parts[0])
                left.append(-1)
                right.append(-1)
        idx += n

        subtree_leaves = [0] * n

        def count_leaves(u):
            if is_leaf[u]:
                return 1
            return count_leaves(left[u]) + count_leaves(right[u])

        for i in range(n):
            subtree_leaves[i] = count_leaves(i)

        def solve(u):
            if is_leaf[u]:
                return value[u]

            left_val = solve(left[u])
            right_val = solve(right[u])

            L = subtree_leaves[u]

            # If L is even: Pieguy's turn (maximize)
            # If L is odd: Piegirl's turn (minimize)
            if L % 2 == 0:
                return max(left_val, right_val)
            else:
                return min(left_val, right_val)

        result = solve(0)
        results.append(str(result))

    return '\n'.join(results)
