Looking at this problem, I need to find either:
1. An independent set of size ⌈√n⌉, or
2. A cycle of length at least ⌈√n⌉

This is a classic graph theory problem. The key insight is that in any connected graph, we can systematically search for these structures using DFS and greedy coloring.

```python
import math
import sys
sys.setrecursionlimit(300000)
from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = defaultdict(list)
    for line in lines[1:]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    sq_n = int(math.ceil(math.sqrt(n)))

    path = []
    best_cycle = []
    found = False

    def dfs(u, p):
        nonlocal found
        path.append(u)

        visited = set(path)

        for v in adj[u]:
            if v == p:
                continue
            if v in visited:
                idx = path.index(v)
                if len(path) - idx >= sq_n:
                    best_cycle = path[idx:]
                    found = True
                    return
            else:
                dfs(v, u)
                if found:
                    return

        path.pop()

    for start in range(1, n + 1):
        path = []
        dfs(start, -1)
        if found:
            break

    if found or best_cycle:
        return f"2\n{len(best_cycle)}\n" + " ".join(map(str, best_cycle))

    # Greedy coloring for independent set
    color = {}
    for u in range(1, n + 1):
        used = 0
        for v in adj[u]:
            if v in color:
                used = max(used, color[v])
        color[u] = used

    for c in color.values():
        group = [u for u, col in color.items() if col == c]
        if len(group) >= sq_n:
            return f"1\n" + " ".join(map(str, group[:sq_n]))

    return f"1\n" + " ".join(map(str, list(color.values())[:sq_n]))
