import collections


def solution(input_str):
    """Complete solution function"""
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    m = int(lines[0])
    results = []

    def is_valid_set(pa, pb, is_5th):
        """Check if (pa, pb) is a valid set score"""
        if is_5th:
            if pa == 15 and pb <= 14:
                return True
            if pb == 15 and pa <= 14:
                return True
            if pa >= 15 and pb >= 15:
                return abs(pa - pb) >= 2
            return False
        else:
            if pa == 25 and pb <= 24:
                return True
            if pb == 25 and pa <= 24:
                return True
            if pa >= 25 and pb >= 25:
                return abs(pa - pb) >= 2
            return False

    def solve_match(a, b):
        best_match_score = None
        best_sets = None
        best_diff = -100

        # Outcomes to try, sorted by A advantage
        outcomes = [
            (3, 0), (3, 1), (3, 2),
            (0, 3), (1, 3), (2, 3)
        ]

        for max_a, max_b in outcomes:
            total_sets = max_a + max_b
            if total_sets > 5 or total_sets < 3:
                continue

            diff = max_a - max_b
            if diff <= best_diff and best_sets:
                continue

            # Generate all patterns (which sets A wins)
            from itertools import combinations
            for win_idxs in combinations(range(total_sets), max_a):
                pattern = [0] * total_sets
                for i in win_idxs:
                    pattern[i] = 1  # A wins this set

                # Try to find valid set scores that sum to (a, b)
                found = False
                current_sets = []

                def search(idx, rem_a, rem_b):
                    nonlocal found
                    if found:
                        return

                    if idx == total_sets:
                        if rem_a == 0 and rem_b == 0:
                            found = True
                            best_sets.append(tuple(current_sets))
                        return

                    a_wins = pattern[idx] == 1
                    is_set_5 = (idx == total_sets - 1)

                    # Generate valid scores efficiently
                    thresholds = [15, 25]
                    thresh = thresholds[1] if not is_set_5 else thresholds[0]

                    # Try normal wins first
                    norm_pa, norm_pb = thresh - 1, thresh
                    if is_set_5:
                        norm_pa, norm_pb = 14, 15 if not a_wins else (15, 14)
                    else:
                        norm_pa, norm_pb = 24, 25 if not a_wins else (25, 24)

                    for pa in range(min(rem_a + 1, 200)):
                        for pb in range(min(rem_b + 1, 200)):
                            if not is_valid_set(pa, pb, is_set_5):
                                continue

                            # Additional checks
                            if a_wins:
                                if pa < thresh and not is_set_5:
                                    continue
                                if pa == thresh and pb > (thresh - 1):
                                    continue
                            else:
                                if pb < thresh and not is_set_5:
                                    continue
                                if pb == thresh and pa > (thresh - 1):
                                    continue

                            if rem_a - pa < 0 or rem_b - pb < 0:
                                continue

                            current_sets.append((pa, pb))
                            search(idx + 1, rem_a - pa, rem_b - pb)
                            current_sets.pop()
                            if found:
                                return

                found = False
                search(0, a, b)

                if found and rem_a == 0 and rem_b == 0:
                    score_str = f"{max_a}:{max_b}"
                    if diff > best_diff or best_sets is None:
                        best_diff = diff
                        best_match_score = score_str
                        best_sets_found = [tuple(current_sets)//2 for current_sets in best_sets]
                        best_sets = best_sets_found
                    break

        if best_sets:
            formatted_sets = " ".join([f"{s[0]}:{s[1]}" for s in best_sets])
            return f"{best_match_score}\n{formatted_sets}"
        return "Impossible"

    output_parts = []
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if not parts:
            continue
        a, b = int(parts[0]), int(parts[1])

        result = solve_match(a, b)
        output_parts.append(result)

    return '\n'.join(output_parts)
